def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    return float(math.log(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    value = 0.0
    total = 0.0
    for element, fraction in s.get('composition', {}).items():
        electrons = props.get(element, {}).get('valence_electrons')
        if fraction is not None and fraction > 0 and electrons is not None and math.isfinite(fraction) and math.isfinite(electrons):
            value += fraction * electrons
            total += fraction
    return float(value / (total * v)) if total > 0 else 0.0

def feature(s):
    density = s.get('density_g_cm3')
    if density is None:
        density = s.get('basic_structure_statistics', {}).get('density_g_cm3')
    if density is None or not math.isfinite(density) or density < 0:
        return 0.0
    return float(density)
